/* ===================== INST·03 — DCF DE CONCESSÃO COM PRAZO DEFINIDO ===================== */
(function(){
  if(!$id('dc-se-n'))return;
  function vp(taxa,hz,f1,gr,ind,pi){
    var vo=0;
    for(var t=1;t<=hz;t++){
      var f=f1*Math.pow(1+gr/100,t-1);
      vo+=f/Math.pow(1+taxa,t);
    }
    var vi=(ind*pi/100)/Math.pow(1+taxa,hz);
    return {vo:vo,vi:vi,tot:vo+vi};
  }
  function upd(){
    var se=numOf($id('dc-se-n'),14.25,2,25);
    var ip=numOf($id('dc-ip-n'),5.16,0,15);
    var pr=numOf($id('dc-pr-n'),0.5,0,10);
    var hz=Math.round(numOf($id('dc-hz-n'),20,1,40));
    var f1=numOf($id('dc-f1-n'),900,50,6000);
    var gr=numOf($id('dc-gr-n'),1,-4,6);
    var ind=numOf($id('dc-in-n'),1200,0,12000);
    var pi=numOf($id('dc-pi-n'),70,0,100);
    var rreal=(1+se/100)/(1+ip/100)-1;
    var taxa=rreal+pr/100;
    if(taxa<=0.001)taxa=0.001;
    var b=vp(taxa,hz,f1,gr,ind,pi);
    var perp=(taxa-gr/100)>0.002?f1/(taxa-gr/100):NaN;
    $id('dc-tx').innerHTML=fmt(taxa*100,2)+'<span class="u">% a.a.</span>';
    $id('dc-vo').innerHTML=fmt(b.vo,0)+'<span class="u">R$ mi</span>';
    $id('dc-vi').innerHTML=fmt(b.vi,0)+'<span class="u">R$ mi</span>';
    $id('dc-ev').innerHTML=fmt(b.tot,0)+'<span class="u">R$ mi</span>';
    $id('dc-pw').textContent=fmt(b.vi/b.tot*100,1)+'% do valor total';
    $id('dc-pp').textContent=(isFinite(perp)?'R$ '+fmt(perp,0)+' mi · '+fmt(perp/b.tot,1)+'× o valor correto':'indefinido: crescimento ≥ taxa');
    var c1=vp(Math.max(taxa-0.01,0.001),hz,f1,gr,ind,pi).tot;
    var c3=vp(taxa+0.01,hz,f1,gr,ind,pi).tot;
    var c4=vp(taxa,Math.max(hz-5,1),f1,gr,ind,pi).tot;
    var mx=Math.max(c1,b.tot,c3,c4,1);
    $id('dc-s1').style.width=clamp(c1/mx*100,2,100)+'%'; $id('dc-v1').textContent=fmt(c1,0);
    $id('dc-s2').style.width=clamp(b.tot/mx*100,2,100)+'%'; $id('dc-v2').textContent=fmt(b.tot,0);
    $id('dc-s3').style.width=clamp(c3/mx*100,2,100)+'%'; $id('dc-v3').textContent=fmt(c3,0);
    $id('dc-s4').style.width=clamp(c4/mx*100,2,100)+'%'; $id('dc-v4').textContent=fmt(c4,0);
    var dtaxa=(c1-c3)/b.tot*100;
    var dhz=(b.tot-c4)/b.tot*100;
    var pesoInd=b.vi/b.tot*100;
    var vd=$id('dc-vd'), cls, txt;
    if(pesoInd>=25){
      cls='per';
      txt='<b>A indenização responde por '+fmt(pesoInd,1)+'% do valor — e ela é a premissa menos verificável do modelo.</b> Com horizonte de '+hz+' anos e probabilidade de recebimento de '+fmt(pi,0)+'%, mais de um quarto do valor calculado depende de um fluxo cuja base legal, cujo valor de apuração e cuja data de recebimento efetivo ainda não estão fixados. Isso não invalida o modelo: <b>exige que a indenização seja apresentada como linha separada</b>, com a norma, o precedente de cálculo e o prazo processual declarados. Um valor único que a embuta no total esconde exatamente a premissa mais frágil.';
    } else if(hz<=7){
      cls='att';
      txt='<b>Horizonte curto: '+hz+' anos.</b> Reduzir cinco anos derruba o valor em '+fmt(dhz,1)+'%, o que é a maior sensibilidade individual deste modelo. Em concessão com prazo remanescente curto, a variável dominante deixa de ser operacional e passa a ser <b>jurídica</b>: existe prorrogação em negociação, com que condicionantes de investimento, e em que estágio formal? A recomendação de prorrogação por um regulador não é a assinatura do aditivo, e a distância entre as duas é a diferença entre cenário e direito.';
    } else if(Math.abs(dtaxa)>=22){
      cls='att';
      txt='<b>Modelo dominado pela taxa: um ponto percentual para cada lado move o valor em '+fmt(Math.abs(dtaxa),1)+'%.</b> Com horizonte de '+hz+' anos e taxa real de '+fmt(taxa*100,2)+'%, a duração do fluxo torna o resultado altamente sensível ao custo de capital — e é exatamente por isso que a taxa não pode ser escolhida por conveniência. Declare os componentes separadamente: taxa livre de risco real derivada da política monetária vigente, prêmio, e a data em que ambos foram verificados. Sem isso, o valor é uma opinião com casas decimais.';
    } else {
      cls='ok';
      txt='<b>Modelo equilibrado entre os componentes.</b> Valor da firma simplificado de R$ '+fmt(b.tot,0)+' milhões, dos quais '+fmt(pesoInd,1)+'% vêm da indenização esperada e o restante dos fluxos operacionais até o termo. Sensibilidade de '+fmt(Math.abs(dtaxa),1)+'% a um ponto percentual de taxa e de '+fmt(dhz,1)+'% a cinco anos de horizonte. <b>Comparação obrigatória:</b> se este mesmo fluxo fosse tratado como perpetuidade, o resultado apareceria como '+(isFinite(perp)?fmt(perp/b.tot,1)+' vezes maior':'indefinido')+' — a diferença entre modelar um direito que expira e supor que ele não expira.';
    }
    vd.className='verdict '+cls; vd.innerHTML=txt;
  }
  ['se','ip','pr','hz','f1','gr','in','pi'].forEach(function(s){pair('dc-'+s+'-n','dc-'+s+'-r',upd);});
  upd();
})();

/* ===================== INST·04 — ROTEIRO CRONOMETRADO DE LEITURA ===================== */
(function(){
  if(!$id('rt-grid'))return;
  var ETAPAS=/* literal ETAPAS: ver dados.ETAPAS */;
  var doc='rel', sel='r1';
  function lista(){return ETAPAS[doc];}
  function byK(k){var f=null;lista().forEach(function(o){if(o.k===k)f=o;});return f;}
  function renderGrid(){
    chips('rt-grid',lista().map(function(o){return {k:o.k,n:o.n,y:o.y};}),'s',function(k){sel=k;renderItem();});
  }
  function renderItem(){
    var p=$id('rt-item'); if(!p)return;
    var e=byK(sel); if(!e){p.innerHTML='';return;}
    p.innerHTML='<div class="yr">'+esc(e.y)+' · '+(doc==='rel'?'Release trimestral':'Formulário de Referência')+'</div>'+
      '<div class="ti">'+esc(e.n)+'</div>'+
      '<div class="bd2">'+e.b+'</div>'+
      '<div class="lg"><b>Esta etapa precisa deixar respondido</b>'+esc(e.q)+'</div>';
  }
  segBind('rt-seg',function(b){doc=b.getAttribute('data-d');sel=lista()[0].k;renderGrid();renderItem();});
  renderGrid(); renderItem();
})();

/* ===================== INST·05 — VERIFICADOR DE LACUNA ===================== */
(function(){
