    o.innerHTML='<div class="ocard gd2"><span class="ok2">Comportamento sob estresse</span>'+a.est+'</div>'+
      '<div class="ocard"><span class="ok2">Pergunta de verificação</span>'+esc(a.ver)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">O que não concluir</span>Arquétipo de controle é dado de entrada da análise, nunca conclusão sobre a qualidade da companhia. Nenhum dos seis é melhor que outro em abstrato: cada um é mais adequado a um horizonte e a uma tolerância a risco diferentes.</div>';
  }
  chips('ct-grid',CASOS.map(function(o){return {k:o.k,n:o.n};}),'c',function(k){sel=k;render();});
  render();
