      '<div class="dc b"><div class="dk">'+esc(c.kb)+'</div><div class="dv">'+esc(c.vb)+'<small>'+esc(c.ub)+'</small></div><div class="dm">'+esc(c.mb)+'</div></div>';
    n.innerHTML='<div class="yr">Mecanismo e consequência</div><div class="ti">'+esc(c.n)+'</div><div class="bd2">'+c.mec+'</div>';
